CREATE TABLE cap19_report_sales (sale_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, product TEXT NOT NULL, category TEXT NOT NULL, quantity INTEGER NOT NULL, unit_price INTEGER NOT NULL);
INSERT INTO cap19_report_sales VALUES (1, 'Asha', 'Cable', 'Accessories', 2, 250), (2, 'Bilal', 'Case', 'Accessories', 1, 400), (3, 'Asha', 'Notebook', 'Stationery', 3, 60), (4, 'Mira', 'Cable', 'Accessories', 1, 250);
SELECT product, SUM(quantity * unit_price) AS revenue FROM cap19_report_sales GROUP BY product ORDER BY revenue DESC, product;

